<template>
  <DialogRoot>
    <DialogTrigger class="contents cursor-pointer">
      <slot name="trigger" />
    </DialogTrigger>
    <DialogPortal>
      <DialogOverlay
        class="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0"
      />
      <DialogContent
        class="fixed left-1/2 top-1/2 z-50 flex max-h-[85vh] w-[95vw] max-w-[32rem] -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center duration-200 focus:outline-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 sm:max-h-[80vh] sm:w-auto"
      >
        <DialogTitle class="sr-only">{{ accessibleTitle }}</DialogTitle>
        <DialogDescription v-if="description" class="sr-only">{{ description }}</DialogDescription>

        <img
          :src="src ?? undefined"
          :alt="alt ?? accessibleTitle"
          class="max-h-[85vh] w-full max-w-full rounded-lg object-contain shadow-2xl sm:max-h-[80vh] sm:w-auto"
          data-testid="image-preview-dialog-image"
        />

        <DialogClose
          class="absolute right-3 top-3 flex size-9 items-center justify-center rounded-full bg-black/50 text-white opacity-90 backdrop-blur-sm transition hover:bg-black/70 hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-white/70 focus:ring-offset-0"
          aria-label="Close image preview"
          data-testid="image-preview-dialog-close"
        >
          <X class="size-5" />
        </DialogClose>
      </DialogContent>
    </DialogPortal>
  </DialogRoot>
</template>

<script setup lang="ts">
import { X } from 'lucide-vue-next';
import {
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogOverlay,
  DialogPortal,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
} from 'reka-ui';

interface Props {
  /** URL of the full-size image to preview. */
  src: string | null | undefined;
  /** Alt text for the image; also used as the accessible dialog title fallback. */
  alt?: string | null;
  /** Accessible dialog title (visually hidden). Falls back to `alt`, then a generic label. */
  title?: string | null;
  /** Optional visually-hidden description for screen readers. */
  description?: string | null;
}

const props = defineProps<Props>();

const accessibleTitle = computed(() => props.title || props.alt || 'Image preview');
</script>
